+<div class="cm-editor cm-s-jupyter">
+<div class="highlight hl-ipython3"><pre><span></span><span class="c1"># Mapa estático de Cap Rate (scatter otimizado: 1 ponto por célula)</span>
+<span class="o">%</span><span class="k">matplotlib</span> inline
+<span class="kn">import</span><span class="w"> </span><span class="nn">matplotlib.pyplot</span><span class="w"> </span><span class="k">as</span><span class="w"> </span><span class="nn">plt</span>
+<span class="kn">import</span><span class="w"> </span><span class="nn">matplotlib.colors</span><span class="w"> </span><span class="k">as</span><span class="w"> </span><span class="nn">mcolors</span>
+
+<span class="n">a</span> <span class="o">=</span> <span class="n">_air_map</span><span class="p">[[</span><span class="s1">'latitude'</span><span class="p">,</span> <span class="s1">'longitude'</span><span class="p">,</span> <span class="s1">'bairro'</span><span class="p">,</span> <span class="s1">'tipo'</span><span class="p">]]</span><span class="o">.</span><span class="n">copy</span><span class="p">()</span>
+<span class="n">a</span> <span class="o">=</span> <span class="n">a</span><span class="o">.</span><span class="n">merge</span><span class="p">(</span><span class="n">_tab_map</span><span class="p">[[</span><span class="s1">'bairro'</span><span class="p">,</span> <span class="s1">'tipo'</span><span class="p">,</span> <span class="s1">'cap_cell'</span><span class="p">]],</span> <span class="n">on</span><span class="o">=</span><span class="p">[</span><span class="s1">'bairro'</span><span class="p">,</span> <span class="s1">'tipo'</span><span class="p">],</span> <span class="n">how</span><span class="o">=</span><span class="s1">'left'</span><span class="p">)</span>
+<span class="n">cel</span> <span class="o">=</span> <span class="n">a</span><span class="o">.</span><span class="n">groupby</span><span class="p">([</span><span class="s1">'bairro'</span><span class="p">,</span> <span class="s1">'tipo'</span><span class="p">],</span> <span class="n">as_index</span><span class="o">=</span><span class="kc">False</span><span class="p">)</span><span class="o">.</span><span class="n">agg</span><span class="p">(</span><span class="n">lat</span><span class="o">=</span><span class="p">(</span><span class="s1">'latitude'</span><span class="p">,</span> <span class="s1">'mean'</span><span class="p">),</span> <span class="n">lon</span><span class="o">=</span><span class="p">(</span><span class="s1">'longitude'</span><span class="p">,</span> <span class="s1">'mean'</span><span class="p">))</span>
+<span class="n">cel</span> <span class="o">=</span> <span class="n">cel</span><span class="o">.</span><span class="n">merge</span><span class="p">(</span><span class="n">_tab_map</span><span class="p">[[</span><span class="s1">'bairro'</span><span class="p">,</span> <span class="s1">'tipo'</span><span class="p">,</span> <span class="s1">'cap_cell'</span><span class="p">]],</span> <span class="n">on</span><span class="o">=</span><span class="p">[</span><span class="s1">'bairro'</span><span class="p">,</span> <span class="s1">'tipo'</span><span class="p">],</span> <span class="n">how</span><span class="o">=</span><span class="s1">'left'</span><span class="p">)</span>
+
+<span class="n">fig</span><span class="p">,</span> <span class="n">ax</span> <span class="o">=</span> <span class="n">plt</span><span class="o">.</span><span class="n">subplots</span><span class="p">(</span><span class="n">figsize</span><span class="o">=</span><span class="p">(</span><span class="mi">10</span><span class="p">,</span> <span class="mi">8</span><span class="p">))</span>
+<span class="n">cmap</span> <span class="o">=</span> <span class="n">plt</span><span class="o">.</span><span class="n">cm</span><span class="o">.</span><span class="n">RdYlGn</span>
+<span class="n">ok</span> <span class="o">=</span> <span class="n">cel</span><span class="o">.</span><span class="n">dropna</span><span class="p">(</span><span class="n">subset</span><span class="o">=</span><span class="p">[</span><span class="s1">'cap_cell'</span><span class="p">])</span>
+<span class="n">norm</span> <span class="o">=</span> <span class="n">mcolors</span><span class="o">.</span><span class="n">Normalize</span><span class="p">(</span><span class="n">vmin</span><span class="o">=</span><span class="n">ok</span><span class="p">[</span><span class="s1">'cap_cell'</span><span class="p">]</span><span class="o">.</span><span class="n">min</span><span class="p">(),</span> <span class="n">vmax</span><span class="o">=</span><span class="n">ok</span><span class="p">[</span><span class="s1">'cap_cell'</span><span class="p">]</span><span class="o">.</span><span class="n">max</span><span class="p">())</span>
+<span class="k">for</span> <span class="n">_</span><span class="p">,</span> <span class="n">r</span> <span class="ow">in</span> <span class="n">ok</span><span class="o">.</span><span class="n">iterrows</span><span class="p">():</span>
