+<span class="n">ax</span><span class="o">.</span><span class="n">scatter</span><span class="p">(</span><span class="n">cel</span><span class="p">[</span><span class="n">cel</span><span class="p">[</span><span class="s1">'cap_cell'</span><span class="p">]</span><span class="o">.</span><span class="n">isna</span><span class="p">()][</span><span class="s1">'lon'</span><span class="p">],</span> <span class="n">cel</span><span class="p">[</span><span class="n">cel</span><span class="p">[</span><span class="s1">'cap_cell'</span><span class="p">]</span><span class="o">.</span><span class="n">isna</span><span class="p">()][</span><span class="s1">'lat'</span><span class="p">],</span>
