 .jp-Spinner {
   position: absolute;
   display: flex;
   justify-content: center;
   align-items: center;
   z-index: 10;
   left: 0;
   top: 0;
   width: 100%;
   height: 100%;
   background: var(--jp-layout-color0);
   outline: none;
 }
 
 .jp-SpinnerContent {
   font-size: 10px;
   margin: 50px auto;
   text-indent: -9999em;
   width: 3em;
   height: 3em;
   border-radius: 50%;
   background: var(--jp-brand-color3);
   background: linear-gradient(
     to right,
     #f37626 10%,
     rgba(255, 255, 255, 0) 42%
   );
   position: relative;
   animation: load3 1s infinite linear, fadeIn 1s;
 }
 
 .jp-SpinnerContent::before {
   width: 50%;
   height: 50%;
   background: #f37626;
   border-radius: 100% 0 0;
   position: absolute;
   top: 0;
   left: 0;
   content: '';
 }
 
 .jp-SpinnerContent::after {
   background: var(--jp-layout-color0);
   width: 75%;
   height: 75%;
   border-radius: 50%;
   content: '';
   margin: auto;
   position: absolute;
   top: 0;
   left: 0;
   bottom: 0;
   right: 0;
 }
 
 @keyframes fadeIn {
   0% {
     opacity: 0;
   }
 
   100% {
     opacity: 1;
   }
 }
 
 @keyframes load3 {
   0% {
     transform: rotate(0deg);
   }
 
   100% {
     transform: rotate(360deg);
   }
 }
 
