 /*-----------------------------------------------------------------------------
 | The Stdin output
 |----------------------------------------------------------------------------*/
 
 .jp-Stdin-prompt {
   color: var(--jp-content-font-color0);
   padding-right: var(--jp-code-padding);
   vertical-align: baseline;
   flex: 0 0 auto;
 }
 
