+}
+.jp-RenderedHTML td, .jp-RenderedMarkdown td {
+  padding: 10px 12px;
+  border-bottom: 1px solid var(--line) !important;
+  color: var(--ink);
+  text-align: right;          /* numeros a direita */
+  font-family: 'IBM Plex Mono', monospace;
+  font-size: 12.5px;
+  white-space: nowrap;
+  background: transparent !important;
+}
+.jp-RenderedHTML td:first-child, .jp-RenderedMarkdown td:first-child,
+.jp-RenderedHTML td:nth-child(2), .jp-RenderedMarkdown td:nth-child(2) {
+  text-align: left;
+  font-family: 'Archivo', sans-serif;
+}
+.jp-RenderedMarkdown tr:last-child td, .jp-RenderedHTML tr:last-child td {
+  border-bottom: none !important;
+}
+/* zebra suave opcional — desligada p/ minimalismo; mas destacamos a linha vencedora dos cards */
+.jp-RenderedMarkdown tr:hover td, .jp-RenderedHTML tr:hover td {
+  background: var(--accent-soft);
+}
+/* esconde indice numerico do pandas */
+table.no-index th:first-child,
+table.no-index td:first-child {
+  display: none;
+}
+
+/* ---- imagens ---- */
+.jp-RenderedMarkdown img, .jp-RenderedHTML img, .jp-RenderedImage img, .jp-OutputArea img {
+  border-radius: 12px;
+  box-shadow: 0 2px 10px rgba(20, 30, 40, 0.08);
+  margin: 12px 0;
+  max-width: 100%;
+  height: auto;
+}
+
+/* folium / mapa interativo embutido */
+.jp-OutputArea img, .leaflet-container, iframe {
+  border-radius: 12px;
+}
+'''
+
+def main():
+    with open(PATH, encoding='utf-8') as f:
+        soup = BeautifulSoup(f.read(), 'html.parser')
+
+    # 1. garante Google Fonts no head
+    head = soup.find('head')
+    has_fonts = any(s.get('href', '').startswith('https://fonts.googleapis.com') for s in head.find_all('link'))
+    if not has_fonts:
+        fonts = soup.new_tag('link', rel='stylesheet',
+                             href='https://fonts.googleapis.com/css2?'
+                                  'family=Archivo:wght@400;500;600;700&'
+                                  'family=IBM+Plex+Mono:wght@400;500;600&display=swap')
+        title = soup.find('title')
+        title.insert_after(fonts)
+
+    # 2. substitui o <style> (apaga o atual e cria novo)
+    old_style = soup.find('style')
+    if old_style:
+        old_style.decompose()
+    style = soup.new_tag('style')
+    style.string = NEW_CSS
+    style.attrs['id'] = 'consultoria-theme'
+    head.append(style)
+
+    with open(PATH, 'w', encoding='utf-8') as f:
+        f.write(str(soup))
+
+    print('pronto. tamanho:', os.path.getsize(PATH) // 1024, 'KB')
+
+
+if __name__ == '__main__':
+    main()
