    --card: #1e2027;
    --card-2: #23262e;
    --ink: #e5e7eb;
    --ink-soft: #9aa1ab;
    --line: #2c2f38;
    --accent: #7fb4d6;
    --accent-soft: #22303c;
    --accent-2: #6ecf8f;
    --quote-bg: #1f2b24;
    --quote-border: #6ecf8f;
    --code-bg: #2a2d35;
    --muted: #6b7280;
  }
}

html, body {
  background: var(--bg) !important;
  color: var(--ink);
  font-family: 'Archivo', 'Inter', -apple-system, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  font-feature-settings: 'tnum' 1;   /* numeros tabulares */
  font-size: 16px;
  line-height: 1.7;
  -webkit-font-smoothing: antialiased;
}

/* destroi o esqueleto do JupyterLab por completo */
.jp-Notebook, main {
  max-width: 1100px !important;
  margin: 0 auto !important;
  padding: 48px 32px !important;
}

.jp-Notebook-cell,
.jp-CodeCell,
.jp-MarkdownCell {
  background: transparent !important;
  box-shadow: none !important;
  border: none !important;
}

/* cada celula vira um card de documento */
.jp-Cell {
  border: 1px solid var(--line) !important;
  border-radius: 14px !important;
  background: var(--card) !important;
  box-shadow: 0 1px 3px rgba(20, 30, 40, 0.04) !important;
  padding: 22px 26px !important;
  margin: 18px 0 18px 0 !important;
}
.jp-Cell:has(> .jp-Cell-outputWrapper:empty) ,
.jp-Cell:has(h1) { /* titulo principal sem card */
  border: none !important;
  background: transparent !important;
  box-shadow: none !important;
  padding: 0 !important;
}

/* esconde TODA sobra de codigo / containers vazios do Jupyter */
.jp-Cell-inputWrapper,
.jp-InputArea,
.jp-CodeMirror,
.jp-InputCollapser,
.jp-OutputCollapser,
.jp-Collapser,
.jp-InputArea-prompt,
.jp-OutputArea-prompt,
.jp-Prompt,
.jp-Metadata,
.jp-Cell-outputCollapser,
.jp-Cell-inputCollapser,
.jp-InputPlaceholder,
.jp-RenderedText .highlight pre {
  display: none !important;
}

/* outputs */
.jp-OutputArea {
  margin: 6px 0 !important;
  padding: 0 !important;
}

/* ---- tipografia ---- */
.jp-RenderedMarkdown, .jp-RenderedHTML {
  color: var(--ink);
  padding: 0 !important;
}
.jp-RenderedMarkdown h1 {
  font-size: 2.2em; font-weight: 700; color: var(--ink);
  letter-spacing: -0.02em;
  margin: 0 0 14px; line-height: 1.2;
  border-bottom: 2px solid var(--accent);
  padding-bottom: 12px;
}
.jp-RenderedMarkdown h2 {
  font-size: 1.5em; font-weight: 700; color: var(--accent);
  letter-spacing: -0.01em;
  margin: 6px 0 10px;
  padding: 4px 0 8px;
  border-bottom: 1px solid var(--line);
}
.jp-RenderedMarkdown h3 {
  font-size: 1.1em; font-weight: 600; color: var(--accent);
  margin: 14px 0 6px;
}
.jp-RenderedMarkdown p { margin: 8px 0; color: var(--ink); }
.jp-RenderedMarkdown li { margin: 5px 0; color: var(--ink); }
.jp-RenderedMarkdown ul, .jp-RenderedMarkdown ol { padding-left: 1.3em; margin: 8px 0; }
.jp-RenderedMarkdown strong { color: var(--ink); font-weight: 700; }
.jp-RenderedMarkdown em { color: var(--ink-soft); }
.jp-RenderedMarkdown hr { border: none; border-top: 1px solid var(--line); margin: 20px 0; }

/* ---- blockquote -> callout ---- */
.jp-RenderedMarkdown blockquote {
  background: var(--quote-bg) !important;
  border-left: 4px solid var(--quote-border) !important;
  border-radius: 0 10px 10px 0;
  color: var(--ink) !important;
  padding: 16px 22px !important;
  margin: 14px 0 !important;
  font-size: 0.97em;
}

/* ---- code inline -> tag ---- */
.jp-RenderedMarkdown code {
  background: var(--code-bg) !important;
  color: var(--ink) !important;
  font-family: 'IBM Plex Mono', 'JetBrains Mono', Consolas, monospace !important;
  font-size: 0.85em;
  padding: 1px 5px;
  border-radius: 5px;
}
.jp-RenderedMarkdown pre {
  background: var(--code-bg);
  border-radius: 10px;
  padding: 14px 18px;
  overflow-x: auto;
  font-family: 'IBM Plex Mono', Consolas, monospace;
  font-size: 0.86em;
  line-height: 1.55;
}

/* ---- tabelas ---- */
.jp-RenderedHTML table, .jp-RenderedMarkdown table {
  border-collapse: collapse;
  width: 100%;
  margin: 14px 0;
  font-size: 13.5px;
  font-family: 'Archivo', sans-serif;
}
.jp-RenderedHTML th, .jp-RenderedMarkdown th {
  background: transparent !important;
  color: var(--muted) !important;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-align: right;
  padding: 0 12px 8px 12px;
  border-bottom: 1.5px solid var(--line);
  white-space: nowrap;
}
.jp-RenderedHTML th:first-child, .jp-RenderedMarkdown th:first-child,
.jp-RenderedHTML th:nth-child(2), .jp-RenderedMarkdown th:nth-child(2) {
  text-align: left;
}
.jp-RenderedHTML td, .jp-RenderedMarkdown td {
  padding: 10px 12px;
  border-bottom: 1px solid var(--line) !important;
  color: var(--ink);
  text-align: right;          /* numeros a direita */
  font-family: 'IBM Plex Mono', monospace;
  font-size: 12.5px;
  white-space: nowrap;
  background: transparent !important;
}
.jp-RenderedHTML td:first-child, .jp-RenderedMarkdown td:first-child,
.jp-RenderedHTML td:nth-child(2), .jp-RenderedMarkdown td:nth-child(2) {
  text-align: left;
  font-family: 'Archivo', sans-serif;
}
.jp-RenderedMarkdown tr:last-child td, .jp-RenderedHTML tr:last-child td {
  border-bottom: none !important;
}
/* zebra suave opcional — desligada p/ minimalismo; mas destacamos a linha vencedora dos cards */
.jp-RenderedMarkdown tr:hover td, .jp-RenderedHTML tr:hover td {
  background: var(--accent-soft);
}
/* esconde indice numerico do pandas */
table.no-index th:first-child,
table.no-index td:first-child {
  display: none;
}

/* ---- imagens ---- */
.jp-RenderedMarkdown img, .jp-RenderedHTML img, .jp-RenderedImage img, .jp-OutputArea img {
  border-radius: 12px;
  box-shadow: 0 2px 10px rgba(20, 30, 40, 0.08);
  margin: 12px 0;
  max-width: 100%;
  height: auto;
}

/* folium / mapa interativo embutido */
.jp-OutputArea img, .leaflet-container, iframe {
  border-radius: 12px;
}
