    # 1. garante Google Fonts no head
    head = soup.find('head')
    has_fonts = any(s.get('href', '').startswith('https://fonts.googleapis.com') for s in head.find_all('link'))
    if not has_fonts:
        fonts = soup.new_tag('link', rel='stylesheet',
                             href='https://fonts.googleapis.com/css2?'
                                  'family=Archivo:wght@400;500;600;700&'
                                  'family=IBM+Plex+Mono:wght@400;500;600&display=swap')
        title = soup.find('title')
        title.insert_after(fonts)

    # 2. substitui o <style> (apaga o atual e cria novo)
    old_style = soup.find('style')
    if old_style:
        old_style.decompose()
    style = soup.new_tag('style')
    style.string = NEW_CSS
    style.attrs['id'] = 'consultoria-theme'
    head.append(style)

    with open(PATH, 'w', encoding='utf-8') as f:
