input.content:
# Override: header neutro maiusculo + preserva cores da matriz deep-dive
from bs4 import BeautifulSoup

PATH = r'analise/apresentacao_sem_codigo.html'

with open(PATH, encoding='utf-8') as f:
    soup = BeautifulSoup(f.read(), 'html.parser')

style = soup.find('style', id='consultoria-theme')
if style is None:
    raise SystemExit('consultoria-theme nao encontrado')

css = style.string

# 1. remove a regra que apagava td com background (preservava nada indevido)
ruim = """table td[style*='background-color'] {
  background: transparent !important;
  color: inherit !important;
  font-weight: 400 !important;
}"""
css = css.replace(ruim, '')

# 2. remove o bloco que zerava classes T_ genericas (se existir)
css = css.replace("""#T_98762 thead th, #T_03616_row0_col0, #T_032un a, [class^='T_'] {
  background: transparent !important;
  color: inherit;
}""", '')

# 3. headers pandas neutros, maiusculos (sobrescreve qualquer cor)
extra = """
/* ---------- final: headers neutros, corpo preservado ---------- */
table thead th, #T_98762 thead th, #T_03616 thead th,
.jp-RenderedHTML th, .jp-RenderedMarkdown th {
  background: transparent !important;
  color: #98a0aa !important;
  font-size: 10.5px !important;
  text-transform: uppercase !important;
  letter-spacing: 0.08em !important;
  font-weight: 600 !important;
  border: none !important;
  border-bottom: 1.5px solid #e7e8e3 !important;
  padding: 0 12px 8px 12px !important;
}
/* corpo: sem bordas verticais, numeros a direita */
table td {
  border: none !important;
  border-bottom: 1px solid #eef0ed !important;
  padding: 9px 12px !important;
  background: transparent !important;
}
/*
  as cores da MATRIZ (deep-dive) sao informacao e ficam;
  apenas mostramos elas por cima sem conflito.
*/
"""
css = css + extra
style.string = css

with open(PATH, 'w', encoding='utf-8') as f:
    f.write(str(soup))

print('OK. tamanho final:', len(css), 'chars')
print('tem regra que apaga td bg?', 'table td[style' in css)
print('tem header neutro?', 'color: #98a0aa' in css)

